-- Huddle Watch Party schema (prototype). Postgres dialect: runs on embedded PGlite locally and on any
-- Postgres (e.g. Neon) when DATABASE_URL is set. IDs are prefixed random strings generated by the server.
-- Room-scoped content (messages, reactions, polls, insights, the event log) is deleted by the purge job
-- after the room's retention window; access ends immediately when the room ends.

-- ---------------------------------------------------------------- identity
CREATE TABLE users (
  id            text PRIMARY KEY,
  phone_e164    text NOT NULL UNIQUE,              -- +91XXXXXXXXXX; never returned to other users
  handle        text UNIQUE,                       -- lowercase public handle, set at first sign-in
  display_name  text,
  team          text,                              -- fan base (MI / CSK) for avatars; optional
  created_at    timestamptz NOT NULL DEFAULT now(),
  last_login_at timestamptz
);

CREATE TABLE sessions (
  id           text PRIMARY KEY,
  token_hash   text NOT NULL UNIQUE,               -- sha256 of the cookie token; the token itself is never stored
  user_id      text NOT NULL REFERENCES users(id) ON DELETE CASCADE,
  created_at   timestamptz NOT NULL DEFAULT now(),
  expires_at   timestamptz NOT NULL,
  last_used_at timestamptz NOT NULL DEFAULT now(),
  revoked_at   timestamptz
);
CREATE INDEX sessions_user ON sessions (user_id);

CREATE TABLE otp_challenges (
  id          text PRIMARY KEY,
  phone_hash  text NOT NULL,                       -- HMAC of the number (rate limits without plaintext)
  code_hash   text,                                -- HMAC of the code (demo provider only); NULL when the SMS provider verifies
  provider    text NOT NULL,
  ip_hash     text NOT NULL,
  attempts    integer NOT NULL DEFAULT 0,
  created_at  timestamptz NOT NULL DEFAULT now(),
  expires_at  timestamptz NOT NULL,
  consumed_at timestamptz
);
CREATE INDEX otp_phone ON otp_challenges (phone_hash, created_at DESC);
CREATE INDEX otp_ip ON otp_challenges (ip_hash, created_at DESC);

-- ---------------------------------------------------------------- match intelligence (shared across rooms)
CREATE TABLE matches (
  id               text PRIMARY KEY,
  fixture_key      text NOT NULL,                  -- which feed script drives this match
  title            text NOT NULL,
  team_a           text NOT NULL,
  team_b           text NOT NULL,
  format           text NOT NULL DEFAULT 'T20',
  source           text NOT NULL,                  -- 'demo_fixture' (simulated replay) for this prototype
  status           text NOT NULL CHECK (status IN ('scheduled', 'live', 'completed')),
  feed_started_at  timestamptz,
  ball_interval_ms integer NOT NULL,
  backfill_until   integer NOT NULL DEFAULT -1,    -- fixture index skipped by a demo jump (no alerts for those)
  created_at       timestamptz NOT NULL DEFAULT now(),
  completed_at     timestamptz
);

CREATE TABLE match_events (
  id                text PRIMARY KEY,
  match_id          text NOT NULL REFERENCES matches(id) ON DELETE CASCADE,
  provider_event_id text NOT NULL,                 -- stable id from the feed; dedupes re-ingestion
  seq               integer NOT NULL,              -- feed order
  kind              text NOT NULL,                 -- 'ball' | 'event' | 'overend'
  data              jsonb NOT NULL,
  occurred_at       timestamptz NOT NULL,          -- when the feed says it happened
  ingested_at       timestamptz NOT NULL DEFAULT now(),
  backfilled        boolean NOT NULL DEFAULT false,
  UNIQUE (match_id, provider_event_id),
  UNIQUE (match_id, seq)
);

CREATE TABLE match_signals (
  id                 text PRIMARY KEY,
  match_id           text NOT NULL REFERENCES matches(id) ON DELETE CASCADE,
  event_id           text NOT NULL REFERENCES match_events(id) ON DELETE CASCADE,
  trigger            text NOT NULL,                -- e.g. wicket_fallen, boundary_burst
  priority           text NOT NULL CHECK (priority IN ('high', 'medium', 'low')),
  label              text NOT NULL,                -- presentation label, e.g. 'Big wicket'
  evidence           jsonb NOT NULL,               -- verified facts that fired the rule
  fact_text          text NOT NULL,                -- deterministic sentence built only from verified data
  dedupe_key         text NOT NULL UNIQUE,
  status             text NOT NULL CHECK (status IN ('pending', 'published', 'suppressed', 'expired')),
  status_reason      text,
  ai_text            text,                         -- optional AI explanation, validated before use
  ai_provider        text,
  ai_model           text,
  created_at         timestamptz NOT NULL DEFAULT now(),
  expires_at         timestamptz NOT NULL,
  published_at       timestamptz
);
CREATE INDEX match_signals_match ON match_signals (match_id, created_at);

-- ---------------------------------------------------------------- rooms and membership
CREATE TABLE rooms (
  id               text PRIMARY KEY,
  name             text,
  room_type        text NOT NULL CHECK (room_type IN ('public', 'private')),
  creator_id       text REFERENCES users(id),
  match_id         text REFERENCES matches(id),
  moderation_level text CHECK (moderation_level IN ('relaxed', 'balanced', 'strict')),
  status           text NOT NULL DEFAULT 'active' CHECK (status IN ('active', 'ended', 'purged')),
  last_seq         integer NOT NULL DEFAULT 0,     -- per-room ordering for the realtime event log
  ai_enabled       boolean NOT NULL DEFAULT true,
  created_at       timestamptz NOT NULL DEFAULT now(),
  updated_at       timestamptz NOT NULL DEFAULT now(),
  ended_at         timestamptz,
  end_reason       text,
  purge_after      timestamptz,
  -- Private rooms always have an owner; public rooms never store a moderation level (policy is server config).
  CHECK (room_type = 'public' OR creator_id IS NOT NULL),
  CHECK (room_type = 'private' OR moderation_level IS NULL)
);
CREATE INDEX rooms_match ON rooms (match_id) WHERE status = 'active';

CREATE TABLE room_members (
  room_id   text NOT NULL REFERENCES rooms(id) ON DELETE CASCADE,
  user_id   text NOT NULL REFERENCES users(id) ON DELETE CASCADE,
  role      text NOT NULL CHECK (role IN ('owner', 'admin', 'member')),
  status    text NOT NULL DEFAULT 'active' CHECK (status IN ('active', 'left', 'removed')),
  joined_at timestamptz NOT NULL DEFAULT now(),
  left_at   timestamptz,
  PRIMARY KEY (room_id, user_id)
);
CREATE INDEX room_members_user ON room_members (user_id) WHERE status = 'active';
CREATE UNIQUE INDEX room_members_one_owner ON room_members (room_id) WHERE role = 'owner';

CREATE TABLE room_invitations (
  id           text PRIMARY KEY,
  room_id      text NOT NULL REFERENCES rooms(id) ON DELETE CASCADE,
  inviter_id   text NOT NULL REFERENCES users(id),
  invitee_id   text NOT NULL REFERENCES users(id),
  status       text NOT NULL CHECK (status IN ('pending', 'accepted', 'declined', 'expired', 'revoked')),
  created_at   timestamptz NOT NULL DEFAULT now(),
  expires_at   timestamptz NOT NULL,
  responded_at timestamptz
);
CREATE UNIQUE INDEX room_invitations_one_pending ON room_invitations (room_id, invitee_id) WHERE status = 'pending';
CREATE INDEX room_invitations_invitee ON room_invitations (invitee_id, status);

CREATE TABLE room_presence (
  room_id      text NOT NULL REFERENCES rooms(id) ON DELETE CASCADE,
  user_id      text NOT NULL REFERENCES users(id) ON DELETE CASCADE,
  state        text NOT NULL CHECK (state IN ('active', 'inactive')),
  last_seen_at timestamptz NOT NULL DEFAULT now(),
  PRIMARY KEY (room_id, user_id)
);

-- ---------------------------------------------------------------- room content (ephemeral)
CREATE TABLE messages (
  id            text PRIMARY KEY,
  room_id       text NOT NULL REFERENCES rooms(id) ON DELETE CASCADE,
  seq           integer,                           -- room sequence when it became visible; NULL while held
  sender_type   text NOT NULL CHECK (sender_type IN ('user', 'ai')),
  sender_id     text REFERENCES users(id),         -- NULL for the AI Co-host
  client_msg_id text,                              -- client idempotency key
  body          text,
  reply_to_id   text REFERENCES messages(id) ON DELETE SET NULL,
  status        text NOT NULL CHECK (status IN ('visible', 'held', 'removed')),
  is_question   boolean NOT NULL DEFAULT false,
  answer_state  text CHECK (answer_state IN ('pending', 'human', 'ai_claimed', 'ai_answered', 'ai_unavailable', 'cancelled')),
  ai_meta       jsonb,                             -- AI messages: provider, model, grounding (never the prompt)
  moderation    jsonb,                             -- decision summary (risk, categories); never a copy of the text
  created_at    timestamptz NOT NULL DEFAULT now(),
  CHECK ((sender_type = 'user') = (sender_id IS NOT NULL))
);
CREATE UNIQUE INDEX messages_user_idem ON messages (room_id, sender_id, client_msg_id) WHERE sender_type = 'user' AND client_msg_id IS NOT NULL;
CREATE UNIQUE INDEX messages_ai_idem ON messages (room_id, client_msg_id) WHERE sender_type = 'ai';
CREATE INDEX messages_room_seq ON messages (room_id, seq);
CREATE INDEX messages_room_created ON messages (room_id, created_at);

CREATE TABLE message_reactions (
  message_id text NOT NULL REFERENCES messages(id) ON DELETE CASCADE,
  user_id    text NOT NULL REFERENCES users(id) ON DELETE CASCADE,
  emoji      text NOT NULL,
  created_at timestamptz NOT NULL DEFAULT now(),
  PRIMARY KEY (message_id, user_id, emoji)
);

CREATE TABLE polls (
  id              text PRIMARY KEY,
  room_id         text NOT NULL REFERENCES rooms(id) ON DELETE CASCADE,
  seq             integer NOT NULL,
  question        text NOT NULL,
  options         jsonb NOT NULL,                  -- [{ "label": "..." }]
  source          text NOT NULL,                   -- 'ai' | 'template'
  requested_by    text REFERENCES users(id),
  idempotency_key text NOT NULL UNIQUE,
  status          text NOT NULL CHECK (status IN ('open', 'closed')),
  closes_at       timestamptz NOT NULL,
  created_at      timestamptz NOT NULL DEFAULT now()
);
CREATE INDEX polls_room ON polls (room_id, created_at);

CREATE TABLE poll_votes (
  poll_id      text NOT NULL REFERENCES polls(id) ON DELETE CASCADE,
  user_id      text NOT NULL REFERENCES users(id) ON DELETE CASCADE,
  option_index integer NOT NULL,
  created_at   timestamptz NOT NULL DEFAULT now(),
  PRIMARY KEY (poll_id, user_id)
);

-- In-app delivery of a match signal to one room (one row per room per signal, so retries cannot duplicate it).
CREATE TABLE room_insights (
  id         text PRIMARY KEY,
  room_id    text NOT NULL REFERENCES rooms(id) ON DELETE CASCADE,
  signal_id  text NOT NULL REFERENCES match_signals(id) ON DELETE CASCADE,
  seq        integer NOT NULL,
  created_at timestamptz NOT NULL DEFAULT now(),
  UNIQUE (room_id, signal_id)
);

-- Realtime outbox: every visible change in a room gets the next room sequence number. Holds ids only.
CREATE TABLE room_events (
  room_id    text NOT NULL REFERENCES rooms(id) ON DELETE CASCADE,
  seq        integer NOT NULL,
  type       text NOT NULL,                        -- message | message_update | poll | insight | member | room
  entity_id  text,
  created_at timestamptz NOT NULL DEFAULT now(),
  PRIMARY KEY (room_id, seq)
);

-- ---------------------------------------------------------------- limits
CREATE TABLE user_send_cooldowns (
  user_id         text PRIMARY KEY REFERENCES users(id) ON DELETE CASCADE,
  next_allowed_at timestamptz NOT NULL
);

-- Sliding-window counters for secondary limits (OTP requests, AI requests, reactions, searches).
CREATE TABLE rate_events (
  bucket     text NOT NULL,
  created_at timestamptz NOT NULL DEFAULT now()
);
CREATE INDEX rate_events_bucket ON rate_events (bucket, created_at);

-- ---------------------------------------------------------------- moderation (minimal audit, no message bodies)
CREATE TABLE moderation_events (
  id             text PRIMARY KEY,
  room_id        text REFERENCES rooms(id) ON DELETE SET NULL,
  actor_id       text,                             -- NULL for automated decisions
  target_user_id text,
  message_id     text,                             -- reference only
  event_type     text NOT NULL,
  severity       text NOT NULL,
  categories     jsonb NOT NULL DEFAULT '[]',
  policy_version text NOT NULL,
  level          text,
  action_taken   text NOT NULL,
  created_at     timestamptz NOT NULL DEFAULT now()
);
CREATE INDEX moderation_events_target ON moderation_events (target_user_id, created_at);

CREATE TABLE reports (
  id                  text PRIMARY KEY,
  kind                text NOT NULL CHECK (kind IN ('message', 'ai_response', 'appeal')),
  room_id             text REFERENCES rooms(id) ON DELETE CASCADE,
  reporter_id         text NOT NULL REFERENCES users(id),
  message_id          text REFERENCES messages(id) ON DELETE SET NULL,
  moderation_event_id text,
  reason              text NOT NULL,
  note                text,
  status              text NOT NULL CHECK (status IN ('open', 'dismissed', 'actioned')),
  created_at          timestamptz NOT NULL DEFAULT now(),
  resolved_by         text,
  resolved_at         timestamptz
);
CREATE UNIQUE INDEX reports_one_per_message ON reports (reporter_id, message_id) WHERE message_id IS NOT NULL;
CREATE INDEX reports_open ON reports (status, created_at);

-- ---------------------------------------------------------------- background jobs (one durable queue)
CREATE TABLE jobs (
  id           text PRIMARY KEY,
  type         text NOT NULL,
  room_id      text REFERENCES rooms(id) ON DELETE CASCADE,
  dedupe_key   text UNIQUE,
  payload      jsonb NOT NULL DEFAULT '{}',        -- ids and deadlines only; never transcripts or secrets
  priority     integer NOT NULL DEFAULT 5,         -- lower runs first
  status       text NOT NULL CHECK (status IN ('queued', 'running', 'done', 'dead', 'cancelled')),
  run_at       timestamptz NOT NULL DEFAULT now(),
  expires_at   timestamptz,
  attempts     integer NOT NULL DEFAULT 0,
  max_attempts integer NOT NULL DEFAULT 3,
  locked_until timestamptz,
  last_error   text,                               -- error category only
  created_at   timestamptz NOT NULL DEFAULT now(),
  updated_at   timestamptz NOT NULL DEFAULT now(),
  finished_at  timestamptz
);
CREATE INDEX jobs_due ON jobs (status, run_at, priority);
CREATE INDEX jobs_room_open ON jobs (room_id) WHERE status IN ('queued', 'running');

-- ---------------------------------------------------------------- AI observability (no prompts, no transcripts)
CREATE TABLE ai_calls (
  id              text PRIMARY KEY,
  correlation_id  text NOT NULL,
  task            text NOT NULL,
  room_id         text,
  user_id         text,
  provider        text,
  model           text,
  attempt         integer NOT NULL,
  outcome         text NOT NULL,                   -- ok | error | skipped
  error_category  text,
  fallback_reason text,
  latency_ms      integer,
  input_tokens    integer,
  output_tokens   integer,
  created_at      timestamptz NOT NULL DEFAULT now()
);
CREATE INDEX ai_calls_created ON ai_calls (created_at);

-- ---------------------------------------------------------------- notifications (delivery metadata only)
CREATE TABLE notification_prefs (
  user_id       text PRIMARY KEY REFERENCES users(id) ON DELETE CASCADE,
  push_momentum boolean NOT NULL DEFAULT true,
  push_answers  boolean NOT NULL DEFAULT false,
  push_invites  boolean NOT NULL DEFAULT true,
  updated_at    timestamptz NOT NULL DEFAULT now()
);

CREATE TABLE push_subscriptions (
  id              text PRIMARY KEY,
  user_id         text NOT NULL REFERENCES users(id) ON DELETE CASCADE,
  endpoint        text NOT NULL UNIQUE,
  p256dh          text NOT NULL,
  auth            text NOT NULL,
  created_at      timestamptz NOT NULL DEFAULT now(),
  last_success_at timestamptz,
  failure_count   integer NOT NULL DEFAULT 0
);
CREATE INDEX push_subscriptions_user ON push_subscriptions (user_id);

-- One row per (source event, recipient). No notification text is stored: it is rebuilt from verified data at send time.
CREATE TABLE notification_deliveries (
  id           text PRIMARY KEY,
  dedupe_key   text NOT NULL UNIQUE,
  recipient_id text NOT NULL REFERENCES users(id) ON DELETE CASCADE,
  room_id      text,
  kind         text NOT NULL,                      -- momentum | invite | answer
  ref_id       text,                               -- signal / invitation / message id
  priority     text NOT NULL,
  channel      text NOT NULL,                      -- push
  status       text NOT NULL CHECK (status IN ('queued', 'sent', 'skipped', 'failed', 'expired')),
  skip_reason  text,
  created_at   timestamptz NOT NULL DEFAULT now(),
  expires_at   timestamptz NOT NULL,
  sent_at      timestamptz
);
CREATE INDEX notification_deliveries_created ON notification_deliveries (created_at);
